const $ = s => document.querySelector(s); let db=null, user=null, members=[], dues=[], payments=[], notes=[], selectedWeek=weekStart(new Date());
const fmtDate = v => v ? new Date(v+'T12:00:00').toLocaleDateString('es-PA',{day:'2-digit',month:'short',year:'numeric'}) : '—';
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekStart(d){const x=new Date(d);x.setHours(12,0,0,0);const day=x.getDay();x.setDate(x.getDate()-(day===0?6:day-1));return iso(x)}
function weekEnd(start){const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+5);return iso(d)}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){$('#toastRoot').innerHTML=`<div class="toast">${escapeHtml(msg)}</div>`;setTimeout(()=>$('#toastRoot').innerHTML='',3200)}
function showAuth(msg=''){ $('#authView').classList.remove('hidden');$('#appView').classList.add('hidden');$('#authMsg').textContent=msg }
function showApp(){ $('#authView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#today').textContent=new Date().toLocaleDateString('es-PA',{weekday:'long',day:'numeric',month:'long',year:'numeric'}); }
function goto(page){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));$('#page-'+page).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('#pageTitle').textContent=({dashboard:'Panel principal',members:'Miembros',dues:'Cuotas semanales',calculator:'Calculadora de compras',vault:'Caja fuerte',notes:'Notas e incidencias'})[page];if(page==='dues')loadDues();if(page==='calculator')renderCalculatorMembers();if(page==='vault')loadVault();if(page==='notes')renderNotes()}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>goto(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>goto(b.dataset.goto));$('#quickAdd').onclick=$('#addMember').onclick=()=>memberModal();$('#addNote').onclick=()=>noteModal();$('#logoutBtn').onclick=async()=>{if(db)await db.auth.signOut();user=null;showAuth('Sesión cerrada.')} ;
$('#memberSearch').oninput=renderMembers;$('#memberFilter').onchange=renderMembers;$('#weekPicker').value=selectedWeek;$('#weekPicker').onchange=()=>{selectedWeek=weekStart(new Date($('#weekPicker').value+'T12:00:00'));$('#weekPicker').value=selectedWeek;loadDues()};$('#currentWeek').onclick=()=>{selectedWeek=weekStart(new Date());$('#weekPicker').value=selectedWeek;loadDues()};
$('#loginForm').onsubmit=async e=>{e.preventDefault();if(!configured){$('#authMsg').textContent='Primero configura SUPABASE_URL y SUPABASE_ANON_KEY en app.js.';return}$('#authMsg').textContent='Verificando acceso…';const {data,error}=await db.auth.signInWithPassword({email:$('#email').value,password:$('#password').value});if(error){$('#authMsg').textContent='No se pudo iniciar sesión: '+error.message;return}user=data.user;await initApp()};
const ROLE_PRICES={'trabajador':650,'sicario':700,'gangster':750,'coordinador':800,'subjefe':850,'jefe':900};
function rolePrice(role){return ROLE_PRICES[String(role||'').trim().toLowerCase()]||0}
function renderCalculatorMembers(){const sel=$('#calcMember');if(!sel)return;const previous=sel.value;sel.innerHTML='<option value="">Selecciona un miembro activo</option>'+members.filter(m=>m.status==='activo').map(m=>'<option value="'+m.id+'">'+escapeHtml(m.ic_name)+'</option>').join('');if(members.some(m=>m.id===previous&&m.status==='activo'))sel.value=previous;updateCalculator()}
function updateCalculator(){if(!$('#calcMember'))return;const m=members.find(x=>x.id===$('#calcMember').value),role=m?.notes_summary||'',price=rolePrice(role),qty=Math.max(0,Math.floor(Number($('#calcQuantity').value)||0));$('#calcRole').value=role;$('#calcPrice').value=price?'$'+price.toLocaleString('en-US'):'Rango sin precio';$('#calcTotal').textContent='$'+(price*qty).toLocaleString('en-US');$('#calcSave').disabled=!(m&&price&&qty>0)}
function clearCalculator(){if(!$('#calculatorForm'))return;$('#calculatorForm').reset();$('#calcQuantity').value='1';updateCalculator()}
$('#calcMember')?.addEventListener('change',updateCalculator);$('#calcQuantity')?.addEventListener('input',updateCalculator);$('#calcClear')?.addEventListener('click',clearCalculator);
$('#calculatorForm')?.addEventListener('submit',async e=>{e.preventDefault();const m=members.find(x=>x.id===$('#calcMember').value),qty=Math.floor(Number($('#calcQuantity').value)||0),price=rolePrice(m?.notes_summary);if(!m||m.status!=='activo'||!price||qty<1){toast('Selecciona un miembro activo con un rango que tenga precio y una cantidad válida.');return}let due=dues.find(d=>d.member_id===m.id);if(!due){await loadDues();due=dues.find(d=>d.member_id===m.id)}if(!due){toast('No se encontró la cuota semanal del miembro.');return}const paidOn=iso(new Date());const result=await db.from('weekly_dues_payments').insert({due_id:due.id,amount_bags:qty,paid_on:paidOn,payer_name:null,note:'Compra realizada - '+m.notes_summary+' - $'+(qty*price).toLocaleString('en-US'),recorded_by:user.id});if(result.error){toast('No se pudo guardar la compra: '+result.error.message);return}const total=payments.filter(p=>p.due_id===due.id).reduce((sum,p)=>sum+Number(p.amount_bags||0),0)+qty;const updateResult=await db.from('weekly_dues').update({delivered:total>=Number(due.required_bags||300),delivered_at:total>=Number(due.required_bags||300)?paidOn:null,recorded_by:user.id}).eq('id',due.id);if(updateResult.error){toast('Compra guardada, pero no se pudo actualizar el estado de la cuota: '+updateResult.error.message);return}const totalPrice=qty*price;clearCalculator();await loadDues();toast('¡Compra realizada! '+qty+' bolsitas · $'+totalPrice.toLocaleString('en-US')+' sumadas a la cuota semanal.')});

let vaultSlots=[],vaultMovements=[];
function vaultActor(){return String(user?.email||'usuario').split('@')[0]||'usuario'}
function vaultIcon(item){const v=String(item.icon_url||'').trim();if(/^(https?:\/\/|assets\/vault\/[a-z0-9-]+\.svg$)/i.test(v))return '<img class="vault-icon" src="'+escapeHtml(v)+'" alt="'+escapeHtml(item.item_name||'Objeto')+'" onerror="this.style.display=\'none\';this.insertAdjacentHTML(\'afterend\',\'<span class=\\\'vault-emoji\\\'>📦</span>\')">';return '<span class="vault-emoji">'+escapeHtml(v||'📦')+'</span>'}
async function loadVault(){if(!db||!user)return;const grid=$('#vaultGrid'),log=$('#vaultLog');if(grid)grid.innerHTML='<p class="muted">Cargando caja fuerte…</p>';const a=await db.from('vault_slots').select('*').order('slot_no');if(a.error){if(grid)grid.innerHTML='<p class="muted">No se pudo cargar la caja fuerte. Si la tabla no existe, ejecuta migration_caja_fuerte.sql en Supabase SQL Editor. Detalle: '+escapeHtml(a.error.message)+'</p>';return}vaultSlots=a.data||[];renderVaultSlots();const b=await db.from('vault_movements').select('*').order('created_at',{ascending:false}).limit(100);if(b.error){if(log)log.innerHTML='<p class="muted">No se pudo cargar el registro: '+escapeHtml(b.error.message)+'</p>';return}vaultMovements=b.data||[];renderVaultLog()}
function renderVaultSlots(){
 const grid=$('#vaultGrid');if(!grid)return;
 const byNo=new Map(vaultSlots.map(x=>[Number(x.slot_no),x]));
 grid.innerHTML=Array.from({length:10},(_,i)=>{
  const n=i+1,x=byNo.get(n)||{slot_no:n,quantity:0};
  if(!x.item_name)return '<div class="vault-slot empty"><span class="empty-label">Casilla '+n+'</span><button class="vault-plus" type="button" data-vault-add="'+n+'" aria-label="Añadir objeto a casilla '+n+'">+</button></div>';
  return '<div class="vault-slot">'+vaultIcon(x)+'<div class="vault-item-name">'+escapeHtml(x.item_name)+'</div><div class="vault-quantity">Cantidad: '+Number(x.quantity).toLocaleString('es-PA')+'</div><div class="vault-slot-actions"><button type="button" class="btn" data-vault-change="-1" data-vault-slot="'+n+'" title="Sacar cantidad">−</button><button type="button" class="btn" data-vault-change="1" data-vault-slot="'+n+'" title="Añadir cantidad">+</button><button type="button" class="btn vault-edit" data-vault-edit="'+n+'">Editar</button></div></div>';
 }).join('');
 grid.querySelectorAll('[data-vault-add]').forEach(button=>{
  button.addEventListener('click',function(event){
   event.preventDefault();event.stopPropagation();
   try{window.openVaultAdd(Number(button.getAttribute('data-vault-add')))}
   catch(error){console.error('Error abriendo la ventana de Caja fuerte:',error);toast('No se pudo abrir la ventana: '+(error.message||error))}
  });
 });
}
function renderVaultLog(){const root=$('#vaultLog');if(!root)return;if(!vaultMovements.length){root.innerHTML='<p class="muted" style="padding:12px">Todavía no hay movimientos registrados.</p>';return}root.innerHTML='<table><thead><tr><th>Fecha</th><th>Usuario</th><th>Casilla</th><th>Objeto</th><th>Cambio</th><th>Antes</th><th>Después</th></tr></thead><tbody>'+vaultMovements.map(x=>'<tr><td>'+new Date(x.created_at).toLocaleString('es-PA')+'</td><td class="vault-log-actor">'+escapeHtml(x.actor_name)+'</td><td>#'+x.slot_no+'</td><td>'+escapeHtml(x.item_name)+'</td><td>'+(Number(x.change_amount)>0?'+':'')+Number(x.change_amount).toLocaleString('es-PA')+'</td><td>'+Number(x.quantity_before).toLocaleString('es-PA')+'</td><td>'+Number(x.quantity_after).toLocaleString('es-PA')+'</td></tr>').join('')+'</tbody></table>'}
const VAULT_PRESETS=[{name:'Fajo de dinero',icon:'assets/vault/fajo-dinero.svg'},{name:'Rollo de billetes',icon:'assets/vault/rollo-billetes.svg'},{name:'Piezas metálicas',icon:'assets/vault/piezas-metalicas.svg'},{name:'Bolsita blanca',icon:'assets/vault/bolsita-blanca.svg'},{name:'Hoja verde',icon:'assets/vault/hoja-verde.svg'}];
// Manejo directo de los botones de Caja fuerte en fase de captura, antes de otros listeners.
document.addEventListener('click',function(event){
  const plus=event.target && event.target.closest ? event.target.closest('[data-vault-add]') : null;
  if(plus){
    event.preventDefault();
    event.stopImmediatePropagation();
    const slot=Number(plus.getAttribute('data-vault-add'));
    if(typeof window.openVaultAdd==='function') window.openVaultAdd(slot);
    else alert('No se pudo cargar la ventana de Caja fuerte. Recarga la página.');
    return;
  }
},true);

window.openVaultAdd = function(slotNo){const root=document.getElementById('modalRoot');if(!root){alert('No se encontró el contenedor de ventanas. Recarga Dark Oak y vuelve a probar.');return}root.innerHTML='<div class="modal-backdrop" data-vault-backdrop><form class="modal" id="vaultAddForm" style="width:min(760px,96vw);max-width:96vw"><div class="modalhead"><h3>Añadir objeto · Casilla '+slotNo+'</h3><button type="button" class="iconbtn" data-vault-close>×</button></div><div class="field"><label>Elige un icono *</label><div class="vault-preset-grid" style="display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;overflow:visible;max-height:none">'+VAULT_PRESETS.map((p,i)=>'<button type="button" class="vault-preset" style="min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:12px 5px" data-vault-preset="'+i+'"><img src="'+p.icon+'" alt="" style="display:block;width:52px;height:52px;object-fit:contain" onerror="this.outerHTML=\'<span style=\\\'font-size:36px\\\'>📦</span>\'"><span style="text-align:center;white-space:normal">'+p.name+'</span></button>').join('')+'</div></div><input type="hidden" name="item_name"><input type="hidden" name="icon_url"><div class="field"><label>Cantidad inicial *</label><input name="quantity" type="number" min="0" step="any" required value="0"></div><div class="controls" style="justify-content:flex-end;margin-top:18px"><button class="btn" type="button" data-vault-close>Cancelar</button><button class="btn primary" type="submit">Guardar objeto</button></div></form></div>';const form=document.getElementById('vaultAddForm');if(form)form.dataset.slot=String(slotNo)}
async function saveVaultMovement(slot,action,before,after,itemName,iconUrl){const delta=after-before;const update=await db.from('vault_slots').update({item_name:itemName,icon_url:iconUrl,quantity:after,updated_by:user.id,updated_at:new Date().toISOString()}).eq('slot_no',slot);if(update.error){toast('No se pudo actualizar la casilla: '+update.error.message);return false}const insert=await db.from('vault_movements').insert({slot_no:slot,item_name:itemName,change_amount:delta,quantity_before:before,quantity_after:after,action,actor_name:vaultActor(),actor_id:user.id});if(insert.error){toast('La cantidad cambió, pero falló el registro: '+insert.error.message);await loadVault();return false}await loadVault();return true}
document.addEventListener('click',async e=>{const preset=e.target.closest('[data-vault-preset]');if(preset){const form=$('#vaultAddForm');const p=VAULT_PRESETS[Number(preset.dataset.vaultPreset)];if(form&&p){form.elements.item_name.value=p.name;form.elements.icon_url.value=p.icon;form.querySelectorAll('[data-vault-preset]').forEach(x=>x.classList.toggle('selected',x===preset))}return}const add=e.target.closest('[data-vault-add]');if(add){openVaultAdd(Number(add.dataset.vaultAdd));return}const close=e.target.closest('[data-vault-close]');if(close){$('#modalRoot').innerHTML='';return}const change=e.target.closest('[data-vault-change]');if(change){const slot=Number(change.dataset.vaultSlot),x=vaultSlots.find(v=>Number(v.slot_no)===slot);if(!x)return;const raw=prompt((Number(change.dataset.vaultChange)>0?'¿Cuántas unidades vas a añadir?':'¿Cuántas unidades vas a sacar?')+'\nCantidad actual: '+x.quantity,'1');if(raw===null)return;const amount=Number(raw);if(!Number.isFinite(amount)||amount<=0){toast('Escribe una cantidad mayor que cero.');return}const after=Number(x.quantity)+(Number(change.dataset.vaultChange)>0?amount:-amount);if(after<0){toast('No puedes dejar una cantidad negativa.');return}await saveVaultMovement(slot,Number(change.dataset.vaultChange)>0?'increase':'decrease',Number(x.quantity),after,x.item_name,x.icon_url);return}const edit=e.target.closest('[data-vault-edit]');if(edit){const slot=Number(edit.dataset.vaultEdit),x=vaultSlots.find(v=>Number(v.slot_no)===slot);if(!x)return;const name=prompt('Nombre del objeto:',x.item_name);if(name===null||!name.trim())return;const icon=prompt('Icono (emoji o URL de imagen):',x.icon_url||'📦');if(icon===null)return;const qtyRaw=prompt('Cantidad actual:',String(x.quantity));if(qtyRaw===null)return;const qty=Number(qtyRaw);if(!Number.isFinite(qty)||qty<0){toast('Cantidad no válida.');return}await saveVaultMovement(slot,'increase',Number(x.quantity),qty,name.trim(),icon.trim());return}});
document.addEventListener('submit',async e=>{if(e.target.id!=='vaultAddForm')return;e.preventDefault();const f=e.target,slot=Number(f.dataset.slot),name=String(f.elements.item_name.value).trim(),icon=String(f.elements.icon_url.value).trim()||'📦',qty=Number(f.elements.quantity.value);if(!name||!Number.isFinite(qty)||qty<0){toast('Revisa el nombre y la cantidad.');return}const existing=vaultSlots.find(x=>Number(x.slot_no)===slot);if(existing?.item_name){toast('Esa casilla ya está ocupada.');return}const before=0;const up=await db.from('vault_slots').update({item_name:name,icon_url:icon,quantity:qty,updated_by:user.id,updated_at:new Date().toISOString()}).eq('slot_no',slot);if(up.error){toast('No se pudo guardar el objeto: '+up.error.message);return}const log=await db.from('vault_movements').insert({slot_no:slot,item_name:name,change_amount:qty,quantity_before:before,quantity_after:qty,action:'add_item',actor_name:vaultActor(),actor_id:user.id});if(log.error){toast('Objeto guardado, pero falló el registro de movimientos: '+log.error.message);return}$('#modalRoot').innerHTML='';await loadVault();toast('Objeto registrado en la casilla '+slot+'.')});

async function init(){if(!configured){$('#configWarning').classList.remove('hidden');return}db=window.supabase.createClient(SUPABASE_URL,SUPABASE_ANON_KEY);const {data}=await db.auth.getSession();if(data.session){user=data.session.user;await initApp()}else showAuth()}
async function initApp(){showApp();await Promise.all([loadMembers(),loadNotes()]);await loadDues()}
async function loadMembers(){const {data,error}=await db.from('members').select('*').order('created_at',{ascending:false});if(error){toast('Error cargando miembros: '+error.message);return}members=data||[];renderMembers();renderDashboard();renderNotes()}
async function loadNotes(){const {data,error}=await db.from('member_notes').select('*, members(ic_name)').order('created_at',{ascending:false});if(!error)notes=data||[];renderNotes()}
async function loadDues(){if(!db||!user)return;$('#weekRange').textContent=`Periodo: ${fmtDate(selectedWeek)} – ${fmtDate(weekEnd(selectedWeek))} · cierre el sábado`;const {data,error}=await db.from('weekly_dues').select('*').eq('week_start',selectedWeek);if(error){toast('Error cargando cuotas: '+error.message);return}dues=data||[];const active=members.filter(m=>m.status==='activo');const existing=new Set(dues.map(d=>d.member_id));const missing=active.filter(m=>!existing.has(m.id));if(missing.length){const rows=missing.map(m=>({member_id:m.id,week_start:selectedWeek,required_bags:300,delivered:false}));const {error:insErr}=await db.from('weekly_dues').insert(rows);if(insErr){toast('No se pudieron preparar cuotas: '+insErr.message)}else{const r=await db.from('weekly_dues').select('*').eq('week_start',selectedWeek);dues=r.data||[]}}if(dues.length){const p=await db.from('weekly_dues_payments').select('*').in('due_id',dues.map(d=>d.id)).order('paid_on',{ascending:true}).order('created_at',{ascending:true});if(p.error){toast('Error cargando abonos: '+p.error.message);return}payments=p.data||[]}else payments=[];renderDues();renderDashboard()}
function renderDashboard(){const active=members.filter(m=>m.status==='activo'),abs=members.filter(m=>m.status==='ausente'),activeDues=dues.filter(d=>active.some(m=>m.id===d.member_id)),paid=activeDues.filter(d=>bagsForDue(d)>=Number(d.required_bags||300)).length,pending=activeDues.filter(d=>bagsForDue(d)<Number(d.required_bags||300)).length;$('#statActive').textContent=active.length;$('#statAbsent').textContent=abs.length;$('#statPaid').textContent=paid;$('#statPending').textContent=pending;const pct=activeDues.length?Math.round(paid/activeDues.length*100):0;$('#progressBar').style.width=pct+'%';$('#progressText').textContent=`${paid} de ${activeDues.length} miembros activos con cuota registrada han entregado (${pct}%).`;$('#recentMembers').innerHTML=members.length?`<table><thead><tr><th>Miembro</th><th>Ingreso</th><th>Estado</th></tr></thead><tbody>${members.slice(0,5).map(m=>`<tr><td><span class="member-name">${escapeHtml(m.ic_name)}</span><span class="sub">${escapeHtml(m.discord_name||'Sin Discord')}</span></td><td>${fmtDate(m.joined_on)}</td><td>${statusPill(m.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todavía no hay miembros registrados.</div>'}
function statusPill(s){return `<span class="pill ${s==='ausente'?'absent':s==='retirado'?'inactive':''}">${({activo:'ACTIVO',ausente:'AUSENTE',retirado:'RETIRADO'})[s]||s}</span>`}
function renderMembers(){if(!$('#membersTable'))return;const q=($('#memberSearch')?.value||'').toLowerCase(),f=$('#memberFilter')?.value||'all';const list=members.filter(m=>(f==='all'||m.status===f)&&[m.ic_name,m.discord_name,m.discord_id].some(v=>(v||'').toLowerCase().includes(q)));$('#membersTable').innerHTML=list.length?`<table><thead><tr><th>Nombre IC</th><th>Discord / ID</th><th>Ingreso</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${list.map(m=>`<tr style="${m.status==='ausente'?'background:#3a2a17':m.status==='retirado'?'opacity:.65':''}"><td><span class="member-name">${escapeHtml(m.ic_name)}</span><span class="sub">${escapeHtml(m.notes_summary||'')}</span></td><td>${escapeHtml(m.discord_name||'—')}<span class="sub">${escapeHtml(m.discord_id||'—')}</span></td><td>${fmtDate(m.joined_on)}</td><td>${statusPill(m.status)}</td><td><div class="row-actions"><button class="btn sm" onclick="memberModal('${m.id}')">Editar</button>${m.status!=='retirado'?`<button class="btn sm" onclick="toggleAbsence('${m.id}','${m.status}')">${m.status==='ausente'?'Reactivar':'Ausencia'}</button><button class="btn sm danger" onclick="retireMember('${m.id}')">Dar de baja</button>`:''}<button class="btn sm" onclick="quickNote('${m.id}')">Nota</button></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No hay miembros que coincidan con la búsqueda.</div>'}
function renderDues(){const active=members.filter(m=>m.status==='activo');const paid=active.filter(m=>{const d=dues.find(x=>x.member_id===m.id);return d&&bagsForDue(d)>=Number(d.required_bags||300)}).length;$('#duesMeta').textContent=`${fmtDate(selectedWeek)} – ${fmtDate(weekEnd(selectedWeek))} · ${paid}/${active.length} cuotas completadas · ${active.reduce((sum,m)=>sum+(dues.find(d=>d.member_id===m.id)?.required_bags||300),0)} bolsitas previstas`;$('#duesTable').innerHTML=active.length?`<table><thead><tr><th>Miembro</th><th>Cuota</th><th>Abonado</th><th>Falta / excedente</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${active.map(m=>{const d=dues.find(x=>x.member_id===m.id);const total=d?bagsForDue(d):0;const goal=d?.required_bags??300;const remaining=Math.max(0,goal-total);const extra=Math.max(0,total-goal);const pct=Math.min(100,Math.round(total/goal*100));return `<tr><td><span class="member-name">${escapeHtml(m.ic_name)}</span><span class="sub">${escapeHtml(m.discord_name||'')}</span></td><td>${goal} bolsitas</td><td><b>${total}</b><div class="progress"><span style="width:${pct}%"></span></div></td><td>${remaining?`Faltan ${remaining}`:extra?`+${extra} excedente`:'Completada'}</td><td><span class="pill ${total>=goal?'paid':'pending'}">${total>=goal?'COMPLETADA':'PARCIAL'}</span></td><td><button class="btn sm good" onclick="paymentModal('${m.id}')">+ Abono / historial</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">Registra miembros para crear las cuotas.</div>'}
function bagsForDue(d){const list=payments.filter(p=>p.due_id===d.id);if(list.length)return list.reduce((sum,p)=>sum+Number(p.amount_bags||0),0);return d.delivered?Number(d.required_bags||300):0}
function paymentModal(memberId){const m=members.find(x=>x.id===memberId),d=dues.find(x=>x.member_id===memberId);if(!m||!d){toast('No se encontró la cuota de este miembro.');return}const list=payments.filter(p=>p.due_id===d.id);const total=bagsForDue(d),remaining=Math.max(0,Number(d.required_bags||300)-total);modal(`<h3>Abonos de ${escapeHtml(m.ic_name)}</h3><p class="muted">Semana del ${fmtDate(selectedWeek)} · Meta ${d.required_bags||300} bolsitas · Acumulado <b>${total}</b> · ${remaining?`Faltan ${remaining}`:`Cuota completada${total>Number(d.required_bags||300)?` (+${total-Number(d.required_bags||300)} excedente)`:''}`}</p><div class="panel" style="padding:12px;margin-bottom:16px"><h4 style="margin:0 0 10px;font-family:Cinzel,serif">Historial de abonos</h4>${list.length?`<div class="tablewrap"><table style="min-width:0"><thead><tr><th>Fecha</th><th>Cantidad</th><th>Registró / recibió</th><th>Nota</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${fmtDate(p.paid_on)}</td><td><b>${Number(p.amount_bags)} bolsitas</b></td><td>${escapeHtml(p.payer_name||'—')}</td><td>${escapeHtml(p.note||'—')}</td><td><button type="button" class="icon-edit" aria-label="Modificar abono" title="Modificar abono" onclick="editPaymentModal('${p.id}','${memberId}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 16.5V20h3.5L18 9.5 14.5 6 4 16.5Z"/><path d="m12.8 7.7 3.5 3.5M14.5 6l1.4-1.4a1.5 1.5 0 0 1 2.1 0l1.4 1.4a1.5 1.5 0 0 1 0 2.1L18 9.5"/></svg></button></td></tr>`).join('')}</tbody></table></div>`:'<div class="muted">Aún no hay abonos esta semana.</div>'}</div><form id="paymentForm"><div class="formgrid"><div class="field"><label>Cantidad de bolsitas *</label><input name="amount_bags" type="number" min="1" step="1" required placeholder="Ej. 100"></div><div class="field"><label>Fecha del abono *</label><input name="paid_on" type="date" required value="${iso(new Date())}"></div><div class="field span2"><label>Quién recibió o registró (opcional)</label><input name="payer_name" placeholder="Nombre del jefe/subjefe"></div><div class="field span2"><label>Nota (opcional)</label><input name="note" placeholder="Ej. entrega en reunión"></div></div><div class="controls" style="justify-content:flex-end"><button type="button" class="btn" onclick="closeModal()">Cerrar</button><button class="btn primary" type="submit">Registrar abono</button></div></form>`);$('#paymentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const row={due_id:d.id,amount_bags:Number(f.get('amount_bags')),paid_on:f.get('paid_on'),payer_name:String(f.get('payer_name')||'').trim()||null,note:String(f.get('note')||'').trim()||null,recorded_by:user.id};if(!Number.isInteger(row.amount_bags)||row.amount_bags<1){toast('La cantidad debe ser un número entero mayor que cero.');return}const {error}=await db.from('weekly_dues_payments').insert(row);if(error){toast('No se pudo registrar el abono: '+error.message);return}const newTotal=total+row.amount_bags;await db.from('weekly_dues').update({delivered:newTotal>=Number(d.required_bags||300),delivered_at:newTotal>=Number(d.required_bags||300)?row.paid_on:null,recorded_by:user.id}).eq('id',d.id);closeModal();await loadDues();paymentModal(memberId);toast('Abono registrado correctamente.')}}
function editPaymentModal(paymentId,memberId){const p=payments.find(x=>x.id===paymentId);if(!p){toast('No se encontró ese abono.');return}modal(`<h3>Modificar abono</h3><form id="editPaymentForm"><div class="formgrid"><div class="field"><label>Cantidad de bolsitas *</label><input name="amount_bags" type="number" min="1" step="1" required value="${Number(p.amount_bags)}"></div><div class="field"><label>Fecha del abono *</label><input name="paid_on" type="date" required value="${p.paid_on}"></div><div class="field span2"><label>Quién recibió o registró (opcional)</label><input name="payer_name" value="${escapeHtml(p.payer_name||'')}"></div><div class="field span2"><label>Nota (opcional)</label><input name="note" value="${escapeHtml(p.note||'')}"></div></div><div class="controls" style="justify-content:space-between"><button type="button" class="btn danger" onclick="deletePayment('${paymentId}','${memberId}')">Borrar abono</button><div class="controls"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">Guardar cambios</button></div></div></form>`);$('#editPaymentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),amount=Number(f.get('amount_bags'));if(!Number.isInteger(amount)||amount<1){toast('La cantidad debe ser un número entero mayor que cero.');return}const {error}=await db.from('weekly_dues_payments').update({amount_bags:amount,paid_on:f.get('paid_on'),payer_name:String(f.get('payer_name')||'').trim()||null,note:String(f.get('note')||'').trim()||null}).eq('id',paymentId);if(error){toast('No se pudo modificar el abono: '+error.message);return}closeModal();await loadDues();paymentModal(memberId);toast('Abono actualizado correctamente.')}}
async function deletePayment(paymentId,memberId){const p=payments.find(x=>x.id===paymentId);if(!p)return;if(!confirm('¿Borrar este abono de '+Number(p.amount_bags)+' bolsitas? Esta acción no se puede deshacer.'))return;const {error}=await db.from('weekly_dues_payments').delete().eq('id',paymentId);if(error){toast('No se pudo borrar el abono: '+error.message);return}const due=dues.find(x=>x.member_id===memberId);if(due){const {data:remaining,error:readErr}=await db.from('weekly_dues_payments').select('amount_bags,paid_on').eq('due_id',due.id);if(readErr){toast('Abono borrado, pero no se pudo recalcular la cuota: '+readErr.message);return}const total=(remaining||[]).reduce((sum,x)=>sum+Number(x.amount_bags||0),0);const lastDate=(remaining||[]).slice().sort((a,b)=>String(a.paid_on).localeCompare(String(b.paid_on))).at(-1)?.paid_on||null;const {error:updateErr}=await db.from('weekly_dues').update({delivered:total>=Number(due.required_bags||300),delivered_at:total>=Number(due.required_bags||300)?lastDate:null}).eq('id',due.id);if(updateErr){toast('Abono borrado, pero no se pudo actualizar el estado: '+updateErr.message);return}}closeModal();await loadDues();paymentModal(memberId);toast('Abono eliminado y cuota recalculada.')}
function modal(html){$('#modalRoot').innerHTML=`<div class="modalback" id="modalBack"><div class="modal">${html}</div></div>`;$('#modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()})}function closeModal(){$('#modalRoot').innerHTML=''}
function memberModal(id=null){const m=members.find(x=>x.id===id)||{ic_name:'',age:'',discord_name:'',discord_id:'',joined_on:iso(new Date()),status:'activo',notes_summary:''};modal(`<h3>${id?'Editar miembro':'Registrar miembro'}</h3><form id="memberForm"><div class="formgrid"><div class="field"><label>Nombre IC *</label><input name="ic_name" required value="${escapeHtml(m.ic_name)}"></div><div class="field"><label>Nombre de Discord</label><input name="discord_name" value="${escapeHtml(m.discord_name||'')}" placeholder="@usuario"></div><div class="field"><label>ID de Discord</label><input name="discord_id" value="${escapeHtml(m.discord_id||'')}"></div><div class="field"><label>Fecha de ingreso *</label><input name="joined_on" type="date" required value="${m.joined_on||iso(new Date())}"></div><div class="field"><label>Estado</label><select name="status"><option value="activo" ${m.status==='activo'?'selected':''}>Activo</option><option value="ausente" ${m.status==='ausente'?'selected':''}>Ausente</option><option value="retirado" ${m.status==='retirado'?'selected':''}>Retirado</option></select></div><div class="field span2"><label>Rango</label><select name="notes_summary" required><option value="" disabled ${!m.notes_summary?'selected':''}>Selecciona un rango</option>${['Jefe','Subjefe','Coordinador','Bunker y Labs','Gangster','Sicario','Trabajador'].map(r=>`<option value="${r}" ${m.notes_summary===r?'selected':''}>${r}</option>`).join('')}${m.notes_summary&&!(['Jefe','Subjefe','Coordinador','Bunker y Labs','Gangster','Sicario','Trabajador'].includes(m.notes_summary))?`<option value="${escapeHtml(m.notes_summary)}" selected>${escapeHtml(m.notes_summary)} (actual)</option>`:''}</select></div></div><div class="controls" style="justify-content:flex-end"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">Guardar miembro</button></div></form>`);$('#memberForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),row=Object.fromEntries(f.entries());row.updated_at=new Date().toISOString();let res;if(id)res=await db.from('members').update(row).eq('id',id);else{row.age=null;row.created_by=user.id;res=await db.from('members').insert(row)}if(res.error){toast('Error: '+res.error.message);return}closeModal();await loadMembers();await loadDues();toast(id?'Miembro actualizado.':'Miembro registrado.')}}
async function toggleAbsence(id,status){const next=status==='ausente'?'activo':'ausente';const {error}=await db.from('members').update({status:next,updated_at:new Date().toISOString()}).eq('id',id);if(error){toast(error.message);return}await loadMembers();toast(next==='ausente'?'Miembro marcado como ausente.':'Miembro reactivado.')}
async function retireMember(id){const m=members.find(x=>x.id===id);if(!m||!confirm(`¿Dar de baja a ${m.ic_name}? Se conservará su historial y sus cuotas anteriores.`))return;const {error}=await db.from('members').update({status:'retirado',left_on:iso(new Date()),updated_at:new Date().toISOString()}).eq('id',id);if(error){toast(error.message);return}await loadMembers();await loadDues();toast('Miembro dado de baja; historial conservado.')}
function quickNote(id){noteModal(id)}function noteModal(memberId=null){const opts=members.filter(m=>m.status!=='retirado').map(m=>`<option value="${m.id}" ${m.id===memberId?'selected':''}>${escapeHtml(m.ic_name)}</option>`).join('');modal(`<h3>Añadir nota interna</h3><form id="noteForm"><div class="field"><label>Miembro *</label><select name="member_id" required>${opts}</select></div><div class="field"><label>Tipo</label><select name="category"><option value="observacion">Observación</option><option value="incidencia">Incidencia disciplinaria</option><option value="cuota">Cuota</option><option value="reconocimiento">Reconocimiento</option></select></div><div class="field"><label>Fecha *</label><input type="date" name="note_date" required value="${iso(new Date())}"></div><div class="field"><label>Detalle *</label><textarea name="body" required placeholder="Describe los hechos de forma concreta…"></textarea></div><div class="controls" style="justify-content:flex-end"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar nota</button></div></form>`);$('#noteForm').onsubmit=async e=>{e.preventDefault();const row=Object.fromEntries(new FormData(e.target).entries());row.created_by=user.id;const {error}=await db.from('member_notes').insert(row);if(error){toast('Error: '+error.message);return}closeModal();await loadNotes();toast('Nota guardada.')}}
function renderNotes(){if(!$('#notesTable'))return;$('#notesTable').innerHTML=notes.length?`<table><thead><tr><th>Fecha</th><th>Miembro</th><th>Tipo</th><th>Detalle</th><th>Acción</th></tr></thead><tbody>${notes.map(n=>`<tr><td>${fmtDate(n.note_date)}</td><td>${escapeHtml(n.members?.ic_name||'Miembro eliminado')}</td><td><span class="pill">${escapeHtml(n.category)}</span></td><td style="white-space:normal;min-width:220px">${escapeHtml(n.body)}</td><td><button class="btn sm danger" onclick="deleteNote('${n.id}')">Eliminar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todavía no hay notas registradas.</div>'}
async function deleteNote(id){if(!confirm('¿Eliminar esta nota?'))return;const {error}=await db.from('member_notes').delete().eq('id',id);if(error){toast(error.message);return}await loadNotes();toast('Nota eliminada.')}
init();
async function init(){if(!configured){$('#configWarning').classList.remove('hidden');return}db=window.supabase.createClient(SUPABASE_URL,SUPABASE_ANON_KEY);const {data}=await db.auth.getSession();if(data.session){user=data.session.user;await initApp()}else showAuth()}
async function initApp(){showApp();await Promise.all([loadMembers(),loadNotes()]);await loadDues()}
async function loadMembers(){const {data,error}=await db.from('members').select('*').order('created_at',{ascending:false});if(error){toast('Error cargando miembros: '+error.message);return}members=data||[];renderMembers();renderDashboard();renderNotes()}
async function loadNotes(){const {data,error}=await db.from('member_notes').select('*, members(ic_name)').order('created_at',{ascending:false});if(!error)notes=data||[];renderNotes()}
async function loadDues(){if(!db||!user)return;$('#weekRange').textContent=`Periodo: ${fmtDate(selectedWeek)} – ${fmtDate(weekEnd(selectedWeek))} · cierre el sábado`;const {data,error}=await db.from('weekly_dues').select('*').eq('week_start',selectedWeek);if(error){toast('Error cargando cuotas: '+error.message);return}dues=data||[];const active=members.filter(m=>m.status==='activo');const existing=new Set(dues.map(d=>d.member_id));const missing=active.filter(m=>!existing.has(m.id));if(missing.length){const rows=missing.map(m=>({member_id:m.id,week_start:selectedWeek,required_bags:300,delivered:false}));const {error:insErr}=await db.from('weekly_dues').insert(rows);if(insErr){toast('No se pudieron preparar cuotas: '+insErr.message)}else{const r=await db.from('weekly_dues').select('*').eq('week_start',selectedWeek);dues=r.data||[]}}if(dues.length){const p=await db.from('weekly_dues_payments').select('*').in('due_id',dues.map(d=>d.id)).order('paid_on',{ascending:true}).order('created_at',{ascending:true});if(p.error){toast('Error cargando abonos: '+p.error.message);return}payments=p.data||[]}else payments=[];renderDues();renderDashboard()}
function renderDashboard(){const active=members.filter(m=>m.status==='activo'),abs=members.filter(m=>m.status==='ausente'),activeDues=dues.filter(d=>active.some(m=>m.id===d.member_id)),paid=activeDues.filter(d=>bagsForDue(d)>=Number(d.required_bags||300)).length,pending=activeDues.filter(d=>bagsForDue(d)<Number(d.required_bags||300)).length;$('#statActive').textContent=active.length;$('#statAbsent').textContent=abs.length;$('#statPaid').textContent=paid;$('#statPending').textContent=pending;const pct=activeDues.length?Math.round(paid/activeDues.length*100):0;$('#progressBar').style.width=pct+'%';$('#progressText').textContent=`${paid} de ${activeDues.length} miembros activos con cuota registrada han entregado (${pct}%).`;$('#recentMembers').innerHTML=members.length?`<table><thead><tr><th>Miembro</th><th>Ingreso</th><th>Estado</th></tr></thead><tbody>${members.slice(0,5).map(m=>`<tr><td><span class="member-name">${escapeHtml(m.ic_name)}</span><span class="sub">${escapeHtml(m.discord_name||'Sin Discord')}</span></td><td>${fmtDate(m.joined_on)}</td><td>${statusPill(m.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todavía no hay miembros registrados.</div>'}
function statusPill(s){return `<span class="pill ${s==='ausente'?'absent':s==='retirado'?'inactive':''}">${({activo:'ACTIVO',ausente:'AUSENTE',retirado:'RETIRADO'})[s]||s}</span>`}
function renderMembers(){if(!$('#membersTable'))return;const q=($('#memberSearch')?.value||'').toLowerCase(),f=$('#memberFilter')?.value||'all';const list=members.filter(m=>(f==='all'||m.status===f)&&[m.ic_name,m.discord_name,m.discord_id].some(v=>(v||'').toLowerCase().includes(q)));$('#membersTable').innerHTML=list.length?`<table><thead><tr><th>Nombre IC</th><th>Discord / ID</th><th>Ingreso</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${list.map(m=>`<tr style="${m.status==='ausente'?'background:#3a2a17':m.status==='retirado'?'opacity:.65':''}"><td><span class="member-name">${escapeHtml(m.ic_name)}</span><span class="sub">${escapeHtml(m.notes_summary||'')}</span></td><td>${escapeHtml(m.discord_name||'—')}<span class="sub">${escapeHtml(m.discord_id||'—')}</span></td><td>${fmtDate(m.joined_on)}</td><td>${statusPill(m.status)}</td><td><div class="row-actions"><button class="btn sm" onclick="memberModal('${m.id}')">Editar</button>${m.status!=='retirado'?`<button class="btn sm" onclick="toggleAbsence('${m.id}','${m.status}')">${m.status==='ausente'?'Reactivar':'Ausencia'}</button><button class="btn sm danger" onclick="retireMember('${m.id}')">Dar de baja</button>`:''}<button class="btn sm" onclick="quickNote('${m.id}')">Nota</button></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No hay miembros que coincidan con la búsqueda.</div>'}
function renderDues(){const active=members.filter(m=>m.status==='activo');const paid=active.filter(m=>{const d=dues.find(x=>x.member_id===m.id);return d&&bagsForDue(d)>=Number(d.required_bags||300)}).length;$('#duesMeta').textContent=`${fmtDate(selectedWeek)} – ${fmtDate(weekEnd(selectedWeek))} · ${paid}/${active.length} cuotas completadas · ${active.reduce((sum,m)=>sum+(dues.find(d=>d.member_id===m.id)?.required_bags||300),0)} bolsitas previstas`;$('#duesTable').innerHTML=active.length?`<table><thead><tr><th>Miembro</th><th>Cuota</th><th>Abonado</th><th>Falta / excedente</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${active.map(m=>{const d=dues.find(x=>x.member_id===m.id);const total=d?bagsForDue(d):0;const goal=d?.required_bags??300;const remaining=Math.max(0,goal-total);const extra=Math.max(0,total-goal);const pct=Math.min(100,Math.round(total/goal*100));return `<tr><td><span class="member-name">${escapeHtml(m.ic_name)}</span><span class="sub">${escapeHtml(m.discord_name||'')}</span></td><td>${goal} bolsitas</td><td><b>${total}</b><div class="progress"><span style="width:${pct}%"></span></div></td><td>${remaining?`Faltan ${remaining}`:extra?`+${extra} excedente`:'Completada'}</td><td><span class="pill ${total>=goal?'paid':'pending'}">${total>=goal?'COMPLETADA':'PARCIAL'}</span></td><td><button class="btn sm good" onclick="paymentModal('${m.id}')">+ Abono / historial</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">Registra miembros para crear las cuotas.</div>'}
function bagsForDue(d){const list=payments.filter(p=>p.due_id===d.id);if(list.length)return list.reduce((sum,p)=>sum+Number(p.amount_bags||0),0);return d.delivered?Number(d.required_bags||300):0}
function paymentModal(memberId){const m=members.find(x=>x.id===memberId),d=dues.find(x=>x.member_id===memberId);if(!m||!d){toast('No se encontró la cuota de este miembro.');return}const list=payments.filter(p=>p.due_id===d.id);const total=bagsForDue(d),remaining=Math.max(0,Number(d.required_bags||300)-total);modal(`<h3>Abonos de ${escapeHtml(m.ic_name)}</h3><p class="muted">Semana del ${fmtDate(selectedWeek)} · Meta ${d.required_bags||300} bolsitas · Acumulado <b>${total}</b> · ${remaining?`Faltan ${remaining}`:`Cuota completada${total>Number(d.required_bags||300)?` (+${total-Number(d.required_bags||300)} excedente)`:''}`}</p><div class="panel" style="padding:12px;margin-bottom:16px"><h4 style="margin:0 0 10px;font-family:Cinzel,serif">Historial de abonos</h4>${list.length?`<div class="tablewrap"><table style="min-width:0"><thead><tr><th>Fecha</th><th>Cantidad</th><th>Registró / recibió</th><th>Nota</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${fmtDate(p.paid_on)}</td><td><b>${Number(p.amount_bags)} bolsitas</b></td><td>${escapeHtml(p.payer_name||'—')}</td><td>${escapeHtml(p.note||'—')}</td><td><button type="button" class="icon-edit" aria-label="Modificar abono" title="Modificar abono" onclick="editPaymentModal('${p.id}','${memberId}')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 16.5V20h3.5L18 9.5 14.5 6 4 16.5Z"/><path d="m12.8 7.7 3.5 3.5M14.5 6l1.4-1.4a1.5 1.5 0 0 1 2.1 0l1.4 1.4a1.5 1.5 0 0 1 0 2.1L18 9.5"/></svg></button></td></tr>`).join('')}</tbody></table></div>`:'<div class="muted">Aún no hay abonos esta semana.</div>'}</div><form id="paymentForm"><div class="formgrid"><div class="field"><label>Cantidad de bolsitas *</label><input name="amount_bags" type="number" min="1" step="1" required placeholder="Ej. 100"></div><div class="field"><label>Fecha del abono *</label><input name="paid_on" type="date" required value="${iso(new Date())}"></div><div class="field span2"><label>Quién recibió o registró (opcional)</label><input name="payer_name" placeholder="Nombre del jefe/subjefe"></div><div class="field span2"><label>Nota (opcional)</label><input name="note" placeholder="Ej. entrega en reunión"></div></div><div class="controls" style="justify-content:flex-end"><button type="button" class="btn" onclick="closeModal()">Cerrar</button><button class="btn primary" type="submit">Registrar abono</button></div></form>`);$('#paymentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const row={due_id:d.id,amount_bags:Number(f.get('amount_bags')),paid_on:f.get('paid_on'),payer_name:String(f.get('payer_name')||'').trim()||null,note:String(f.get('note')||'').trim()||null,recorded_by:user.id};if(!Number.isInteger(row.amount_bags)||row.amount_bags<1){toast('La cantidad debe ser un número entero mayor que cero.');return}const {error}=await db.from('weekly_dues_payments').insert(row);if(error){toast('No se pudo registrar el abono: '+error.message);return}const newTotal=total+row.amount_bags;await db.from('weekly_dues').update({delivered:newTotal>=Number(d.required_bags||300),delivered_at:newTotal>=Number(d.required_bags||300)?row.paid_on:null,recorded_by:user.id}).eq('id',d.id);closeModal();await loadDues();paymentModal(memberId);toast('Abono registrado correctamente.')}}
function editPaymentModal(paymentId,memberId){const p=payments.find(x=>x.id===paymentId);if(!p){toast('No se encontró ese abono.');return}modal(`<h3>Modificar abono</h3><form id="editPaymentForm"><div class="formgrid"><div class="field"><label>Cantidad de bolsitas *</label><input name="amount_bags" type="number" min="1" step="1" required value="${Number(p.amount_bags)}"></div><div class="field"><label>Fecha del abono *</label><input name="paid_on" type="date" required value="${p.paid_on}"></div><div class="field span2"><label>Quién recibió o registró (opcional)</label><input name="payer_name" value="${escapeHtml(p.payer_name||'')}"></div><div class="field span2"><label>Nota (opcional)</label><input name="note" value="${escapeHtml(p.note||'')}"></div></div><div class="controls" style="justify-content:space-between"><button type="button" class="btn danger" onclick="deletePayment('${paymentId}','${memberId}')">Borrar abono</button><div class="controls"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">Guardar cambios</button></div></div></form>`);$('#editPaymentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),amount=Number(f.get('amount_bags'));if(!Number.isInteger(amount)||amount<1){toast('La cantidad debe ser un número entero mayor que cero.');return}const {error}=await db.from('weekly_dues_payments').update({amount_bags:amount,paid_on:f.get('paid_on'),payer_name:String(f.get('payer_name')||'').trim()||null,note:String(f.get('note')||'').trim()||null}).eq('id',paymentId);if(error){toast('No se pudo modificar el abono: '+error.message);return}closeModal();await loadDues();paymentModal(memberId);toast('Abono actualizado correctamente.')}}
async function deletePayment(paymentId,memberId){const p=payments.find(x=>x.id===paymentId);if(!p)return;if(!confirm('¿Borrar este abono de '+Number(p.amount_bags)+' bolsitas? Esta acción no se puede deshacer.'))return;const {error}=await db.from('weekly_dues_payments').delete().eq('id',paymentId);if(error){toast('No se pudo borrar el abono: '+error.message);return}const due=dues.find(x=>x.member_id===memberId);if(due){const {data:remaining,error:readErr}=await db.from('weekly_dues_payments').select('amount_bags,paid_on').eq('due_id',due.id);if(readErr){toast('Abono borrado, pero no se pudo recalcular la cuota: '+readErr.message);return}const total=(remaining||[]).reduce((sum,x)=>sum+Number(x.amount_bags||0),0);const lastDate=(remaining||[]).slice().sort((a,b)=>String(a.paid_on).localeCompare(String(b.paid_on))).at(-1)?.paid_on||null;const {error:updateErr}=await db.from('weekly_dues').update({delivered:total>=Number(due.required_bags||300),delivered_at:total>=Number(due.required_bags||300)?lastDate:null}).eq('id',due.id);if(updateErr){toast('Abono borrado, pero no se pudo actualizar el estado: '+updateErr.message);return}}closeModal();await loadDues();paymentModal(memberId);toast('Abono eliminado y cuota recalculada.')}
function modal(html){$('#modalRoot').innerHTML=`<div class="modalback" id="modalBack"><div class="modal">${html}</div></div>`;$('#modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()})}function closeModal(){$('#modalRoot').innerHTML=''}
function memberModal(id=null){const m=members.find(x=>x.id===id)||{ic_name:'',age:'',discord_name:'',discord_id:'',joined_on:iso(new Date()),status:'activo',notes_summary:''};modal(`<h3>${id?'Editar miembro':'Registrar miembro'}</h3><form id="memberForm"><div class="formgrid"><div class="field"><label>Nombre IC *</label><input name="ic_name" required value="${escapeHtml(m.ic_name)}"></div><div class="field"><label>Nombre de Discord</label><input name="discord_name" value="${escapeHtml(m.discord_name||'')}" placeholder="@usuario"></div><div class="field"><label>ID de Discord</label><input name="discord_id" value="${escapeHtml(m.discord_id||'')}"></div><div class="field"><label>Fecha de ingreso *</label><input name="joined_on" type="date" required value="${m.joined_on||iso(new Date())}"></div><div class="field"><label>Estado</label><select name="status"><option value="activo" ${m.status==='activo'?'selected':''}>Activo</option><option value="ausente" ${m.status==='ausente'?'selected':''}>Ausente</option><option value="retirado" ${m.status==='retirado'?'selected':''}>Retirado</option></select></div><div class="field span2"><label>Rango</label><select name="notes_summary" required><option value="" disabled ${!m.notes_summary?'selected':''}>Selecciona un rango</option>${['Jefe','Subjefe','Coordinador','Bunker y Labs','Gangster','Sicario','Trabajador'].map(r=>`<option value="${r}" ${m.notes_summary===r?'selected':''}>${r}</option>`).join('')}${m.notes_summary&&!(['Jefe','Subjefe','Coordinador','Bunker y Labs','Gangster','Sicario','Trabajador'].includes(m.notes_summary))?`<option value="${escapeHtml(m.notes_summary)}" selected>${escapeHtml(m.notes_summary)} (actual)</option>`:''}</select></div></div><div class="controls" style="justify-content:flex-end"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">Guardar miembro</button></div></form>`);$('#memberForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),row=Object.fromEntries(f.entries());row.updated_at=new Date().toISOString();let res;if(id)res=await db.from('members').update(row).eq('id',id);else{row.age=null;row.created_by=user.id;res=await db.from('members').insert(row)}if(res.error){toast('Error: '+res.error.message);return}closeModal();await loadMembers();await loadDues();toast(id?'Miembro actualizado.':'Miembro registrado.')}}
async function toggleAbsence(id,status){const next=status==='ausente'?'activo':'ausente';const {error}=await db.from('members').update({status:next,updated_at:new Date().toISOString()}).eq('id',id);if(error){toast(error.message);return}await loadMembers();toast(next==='ausente'?'Miembro marcado como ausente.':'Miembro reactivado.')}
async function retireMember(id){const m=members.find(x=>x.id===id);if(!m||!confirm(`¿Dar de baja a ${m.ic_name}? Se conservará su historial y sus cuotas anteriores.`))return;const {error}=await db.from('members').update({status:'retirado',left_on:iso(new Date()),updated_at:new Date().toISOString()}).eq('id',id);if(error){toast(error.message);return}await loadMembers();await loadDues();toast('Miembro dado de baja; historial conservado.')}
function quickNote(id){noteModal(id)}function noteModal(memberId=null){const opts=members.filter(m=>m.status!=='retirado').map(m=>`<option value="${m.id}" ${m.id===memberId?'selected':''}>${escapeHtml(m.ic_name)}</option>`).join('');modal(`<h3>Añadir nota interna</h3><form id="noteForm"><div class="field"><label>Miembro *</label><select name="member_id" required>${opts}</select></div><div class="field"><label>Tipo</label><select name="category"><option value="observacion">Observación</option><option value="incidencia">Incidencia disciplinaria</option><option value="cuota">Cuota</option><option value="reconocimiento">Reconocimiento</option></select></div><div class="field"><label>Fecha *</label><input type="date" name="note_date" required value="${iso(new Date())}"></div><div class="field"><label>Detalle *</label><textarea name="body" required placeholder="Describe los hechos de forma concreta…"></textarea></div><div class="controls" style="justify-content:flex-end"><button type="button" class="btn" onclick="closeModal()">Cancelar</button><button class="btn primary">Guardar nota</button></div></form>`);$('#noteForm').onsubmit=async e=>{e.preventDefault();const row=Object.fromEntries(new FormData(e.target).entries());row.created_by=user.id;const {error}=await db.from('member_notes').insert(row);if(error){toast('Error: '+error.message);return}closeModal();await loadNotes();toast('Nota guardada.')}}
function renderNotes(){if(!$('#notesTable'))return;$('#notesTable').innerHTML=notes.length?`<table><thead><tr><th>Fecha</th><th>Miembro</th><th>Tipo</th><th>Detalle</th><th>Acción</th></tr></thead><tbody>${notes.map(n=>`<tr><td>${fmtDate(n.note_date)}</td><td>${escapeHtml(n.members?.ic_name||'Miembro eliminado')}</td><td><span class="pill">${escapeHtml(n.category)}</span></td><td style="white-space:normal;min-width:220px">${escapeHtml(n.body)}</td><td><button class="btn sm danger" onclick="deleteNote('${n.id}')">Eliminar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Todavía no hay notas registradas.</div>'}
async function deleteNote(id){if(!confirm('¿Eliminar esta nota?'))return;const {error}=await db.from('member_notes').delete().eq('id',id);if(error){toast(error.message);return}await loadNotes();toast('Nota eliminada.')}
init();
